create or replace function public.admin_update_feedback(p_id uuid,p_status text,p_reply text default null) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_manager() then raise exception 'Manager required'; end if; if p_status not in ('OPEN','IN_REVIEW','ANSWERED','CLOSED') then raise exception 'Invalid status'; end if; update public.feedback_posts set status=p_status,admin_reply=coalesce(p_reply,admin_reply),replied_by=case when p_reply is null then replied_by else auth.uid() end,replied_at=case when p_reply is null then replied_at else now() end where id=p_id; if not found then raise exception 'Feedback not found'; end if; end; $$;
create or replace function public.admin_create_notice(p_title text,p_content text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if not private.is_manager() then raise exception 'Manager required'; end if; insert into public.notices(title,content,author_id) values(p_title,p_content,auth.uid()) returning id into v_id; return v_id; end; $$;
create or replace function public.admin_delete_notice(p_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_manager() then raise exception 'Manager required'; end if; delete from public.notices where id=p_id; end; $$;
revoke all on function public.admin_update_feedback(uuid,text,text),public.admin_create_notice(text,text),public.admin_delete_notice(uuid) from public,anon; grant execute on function public.admin_update_feedback(uuid,text,text),public.admin_create_notice(text,text),public.admin_delete_notice(uuid) to authenticated;
